import{d as u,C as t,o as c,c as m,j as a,a as s,E as r,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第十二章","description":"从感官逐物与难得之货，理解为腹不为目的取舍。","frontmatter":{"title":"道德经第十二章","description":"从感官逐物与难得之货，理解为腹不为目的取舍。","category":"guide","aliases":["道德经第十二章","老子第十二章","dao de jing chapter 12"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-12.md","filePath":"daoism/dao-de-jing/chapter-12.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-12.md"},w=u({...p,setup(g){const n=[{id:"senses-and-excess",label:"五色令人目盲",showLabel:!0,sentences:[[{text:"五色",glossary:"wuse"},"令人目盲，",{text:"五音",glossary:"wuyin"},"令人耳聋，"],[{text:"五味",glossary:"wuwei-tastes"},"令人口",{text:"爽",glossary:"shuang"},"，"]],note:["【白话】繁多的色彩使人目不明，繁多的声音使人听不清，繁多的滋味使人的味觉失常。这里连用盲、聋、爽，写耳目口被感官刺激牵引、反失其正常作用。","【王弼注择要】「爽，差失也。失口之用，故谓之爽。」又说「不以顺性命，反以伤自然」。王弼将问题放在失去本来作用，不是把爽解释为爽快。","【读法】五色、五音、五味各举感官对象的一类，文中可概括多样刺激。原文的强烈措辞不是现代医学关于色彩、音乐或食物必然致病的结论。"]},{id:"pursuit-and-obstruction",label:"难得之货令人行妨",showLabel:!0,sentences:[["驰骋",{text:"畋猎",glossary:"tianlie"},"令人心发狂，"],["难得之货令人行",{text:"妨",glossary:"fang"},"。"]],note:["【白话】纵马追逐、游猎使人心神躁乱；难以得到的珍贵货物，使人的行为受到妨碍、偏离正路。","【王弼注择要】「难得之货，塞人正路，故令人行妨也。」注所批评的不只是有某件物品，更是追逐稀贵之物怎样堵塞人的正当行动。","【读法】这一段从感官转到追逐与行为。问题不只在看见什么，也在为得到它付出什么、让什么支配选择。畋与田在本章所据录文中写法不同，义同田猎。"]},{id:"nourishing-rather-than-serving-desire",label:"为腹不为目",showLabel:!0,sentences:[["是以圣人",{text:"为腹",glossary:"weifu"},"不",{text:"为目",glossary:"weimu"},"，故去彼取此。"]],note:["【白话】因此，圣人的取向在于满足生命的实在需要，不在于无休止地追逐耳目所好，所以舍去被外物役使的一面，选择能养护自身的一面。","【王弼注择要】「为腹者以物养己，为目者以物役己。」腹与目在注中形成养己、役己的对照，不能只按身体器官分出谁好谁坏。","【读法】彼承接逐物而失其用的一面，此指养己的一面。为腹也不等于放纵食欲；五味令人口爽已经提醒，吃喝同样可能由养身转为役身。"]}],o=[{id:"wuse",term:"五色",sense:1},{id:"wuyin",term:"五音",sense:1},{id:"wuwei-tastes",term:"五味",sense:1},{id:"shuang",term:"爽",sense:1},{id:"tianlie",term:"畋猎",sense:1},{id:"fang",term:"妨",sense:1,context:"行读 xíng，指行为、行事受到阻碍而失其正。"},{id:"weifu",term:"为腹",sense:1},{id:"weimu",term:"为目",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十二章",tabindex:"-1"},[s("道德经第十二章 "),a("a",{class:"header-anchor",href:"#道德经第十二章","aria-label":'Permalink to "道德经第十二章"'},"​")],-1)),r(i,{title:"是用物养己，还是让物役己？",summary:"本章先写耳目口的失常，再写心与行为被追逐牵动，最后以腹、目作取舍。沿着王弼的养己与役己来读，比把本章看成一张感官禁令更能抓住其问题。",points:[{label:"先读",text:"盲、聋、爽、狂、妨分别落在哪里？"},{label:"再辨",text:"外物怎样从生活所需变成行动的主人？"},{label:"后想",text:"去彼取此，要改变哪一种关系？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[s("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:n,glossary:o,tone:"ink",density:"comfortable","aria-label":"《道德经》第十二章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[s("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"五味令人口爽。",tone:"辨古义",guide:"爽在这里是差失，意为味觉失其正常作用。若按今天的爽快来读，恰好会把批评读成赞许。"},{text:"难得之货令人行妨。",tone:"看行动",guide:"从感官刺激转到稀贵之物，判断也从感受延伸到行为。为得到一件东西而失去正路，是比拥有多少更深的问题。"},{text:"是以圣人为腹不为目。",tone:"辨取舍",guide:"腹与目承载两种对待外物的方式。以物养己，问需要是否得到安顿；以物役己，则让新鲜、稀缺与外在评价不断加码。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[s("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:o}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-五种失常怎样连成一条线" tabindex="-1">象：五种失常怎样连成一条线？ <a class="header-anchor" href="#象-五种失常怎样连成一条线" aria-label="Permalink to &quot;象：五种失常怎样连成一条线？&quot;">​</a></h3><p>前三项落在看、听、尝，第四项转到心神，第五项转到行事。它们共同描写逐物之后反失其用的状态。结尾不再增加一项禁令，而是提出对待外物的取向：让物养人，还是让人服从物？</p><h3 id="理-为什么「为腹」没有落入另一种感官追求" tabindex="-1">理：为什么「为腹」没有落入另一种感官追求？ <a class="header-anchor" href="#理-为什么「为腹」没有落入另一种感官追求" aria-label="Permalink to &quot;理：为什么「为腹」没有落入另一种感官追求？&quot;">​</a></h3><p>腹取养生所需之象，目取向外驰逐之象。王弼以养己、役己解释，已经提示这是一组关系譬喻。若将为腹理解成尽情满足口腹，便与前面批评五味使口失用相冲突。</p><h3 id="用-审美、娱乐与消费应怎样取舍" tabindex="-1">用：审美、娱乐与消费应怎样取舍？ <a class="header-anchor" href="#用-审美、娱乐与消费应怎样取舍" aria-label="Permalink to &quot;用：审美、娱乐与消费应怎样取舍？&quot;">​</a></h3><p>可以检查它们是否仍服务休息、体验与生活，还是不断挤占睡眠、注意力、财力与承诺。具体限度因人因境而异。停止一种失衡的追逐，不要求同时取消音乐、美食或审美活动的价值。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先辨需要，再看刺激。</strong> 刷资讯、购物或娱乐前，可以先问自己要获得什么，结束时再看是否已经得到。如果目标只是休息，却越看越疲惫，便有理由调整时长与内容。</p><p><strong>把稀缺与值得分开判断。</strong> 限量、排行榜与他人羡慕能够制造追逐的理由，却不能代替用途和承受能力的判断。买与不买都回到实际生活，而非把消费多少变成道德高低。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：最近一次追逐新鲜或稀缺的事物，是在养我，还是开始役使我？我会用什么具体迹象判断它们的界线？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文沿用本站「畋猎」；HFL 电子录文作「田猎」，本页取田猎义，未据此更换正文用字。</li><li>「爽」据王弼注取差失、失其用；「为腹／为目」循养己与役己解释，不按器官本身作价值判断。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，007b–008a</a>。</p>',15))])}}});export{_ as __pageData,w as default};
